@Test
public void testModifyReportTemplateWithNameUnchanged() throws ServiceException, IOException {
    // Given
    String templateId = "43e30abc-4193-9620-8888";
    ReportTemplate template = buildTemplateRequest();
    ReportTemplateInput input = new ReportTemplateInput();
    input.setTemplate(template);

    // 模拟数据库中存在同名模板，但就是当前正在修改的模板
    ReportTemplatePO existingTemplateWithSameName = new ReportTemplatePO();
    existingTemplateWithSameName.setTemplateId(templateId);
    existingTemplateWithSameName.setTemplateName(template.getBasicInfo().getName());
    when(reportTemplateDao.selectByTemplateId(templateId)).thenReturn(testData);
    when(reportTemplateDao.selectByTemplateName(template.getBasicInfo().getName())).thenReturn(existingTemplateWithSameName);

    // When
    ReportTemplate result = intelligentTemplateDelegate.modifyReportTemplate(httpContext, templateId, input);

    // Then
    assertNotNull(result);
    verify(reportTemplateDao, times(1)).selectByTemplateId(templateId);
    verify(reportTemplateDao, times(1)).selectByTemplateName(template.getBasicInfo().getName());
    verify(reportTemplateDao, times(1)).updateByTemplateId(any(String.class), any(ReportTemplatePO.class));
}

@Test(expected = ServiceException.class)
public void testModifyReportTemplateWithNameAlreadyExists() throws ServiceException, IOException {
    // Given
    String templateId = "43e30abc-4193-9620-8888";
    ReportTemplate template = buildTemplateRequest();
    ReportTemplateInput input = new ReportTemplateInput();
    input.setTemplate(template);

    // 模拟数据库中已存在同名模板（不是当前正在修改的模板）
    ReportTemplatePO existingTemplate = new ReportTemplatePO();
    existingTemplate.setTemplateId("different-template-id");
    existingTemplate.setTemplateName(template.getBasicInfo().getName());
    when(reportTemplateDao.selectByTemplateId(templateId)).thenReturn(testData);
    when(reportTemplateDao.selectByTemplateName(template.getBasicInfo().getName())).thenReturn(existingTemplate);

    // When
    intelligentTemplateDelegate.modifyReportTemplate(httpContext, templateId, input);

    // Then - 应该抛出ServiceException异常
}

